import type { LinearGenomeViewModel } from '@jbrowse/plugin-linear-genome-view'

type LGV = LinearGenomeViewModel

function isLinearGenomeView(view: AbstractViewModel): view is LGV {
  return view.type === 'LinearGenomeView'
}

export interface IRegion {
  refName: string
  start: number
  end: number
}

/**
 * A search to run, discriminated by the program that runs it: the two arms
 * differ in which databases they name and in whether an aligner runs at all, so
 * splitting them is what lets doLaunchBlast read the database without asserting
 * whose it is.
 *
 * The field is still `blastDatabase` rather than `database`: it is persisted in
 * session snapshots and in the IndexedDB result cache, so renaming it would
 * orphan every row already written.
 */
export type BlastParams = {
  /** plain JSON, not a Feature: see TranscriptRef */
  selectedTranscript?: TranscriptRef
  /**
   * The query. The dialog always supplies it, translated from the transcript
   * the user picked. A session spec may instead name a UniProt `accession`
   * and have the sequence fetched at launch, or name a `connectedTranscript`
   * on the view and have it translated from the genome (see
   * resolveConnectedTranscript).
   */
  proteinSequence?: string
  accession?: string
  /** hits to keep: phmmer's `nhits`, blastp's `alignments`; 100 when omitted */
  maxHits?: number
} & (
  | {
      /** absent on params written before phmmer existed, which were all blastp */
      searchProgram?: 'blastp'
      blastDatabase: BlastDatabase
      msaAlgorithm: MsaAlgorithm
    }
  | {
      searchProgram: 'phmmer'
      /** phmmer names its databases its own way: `swissprot`, not `uniprotkb_swissprot` */
      blastDatabase: PhmmerDatabase
      /** phmmer aligns as it searches, so there is no aligner to choose */
      msaAlgorithm?: undefined
    }
)

/**
 * Where the homolog set comes from. NCBI's ortholog sets cover vertebrates and
 * insects; PANTHER's span its 144 reference proteomes, human to yeast to
 * Arabidopsis; a UniRef cluster is every UniProtKB entry within 50% (or 90%)
 * identity of the query, one per species, from any organism at all -- and the
 * one source of the three whose rows need no ortholog call, only UniProt's
 * REST api (see utils/unirefHomologs.ts).
 */
export const orthologSources = ['ncbi', 'panther', 'uniref'] as const
export type OrthologSource = (typeof orthologSources)[number]

export interface OrthologParams {
  /** NCBI taxon id of the assembly the query gene came from */
  taxId: number
  /** `ncbi` when omitted, so every launch written before this key keeps its meaning */
  source?: OrthologSource
  /** UniRef only: the cluster identity level, 50 when omitted */
  identity?: UnirefIdentity
  /**
   * UniRef only: keep members from reference proteomes, which is what makes a
   * cluster one good entry per species rather than every strain and isolate
   * UniProtKB holds. `true` when omitted.
   */
  referenceProteomesOnly?: boolean
  /**
   * taxon ids to include as rows. The query taxon has its own row already, so
   * it is excluded from this set whether or not it is named.
   * Omitted means every species NCBI has an ortholog for, in its report order,
   * which is what a launch that just wants "this gene across species" wants.
   */
  taxa?: number[]
  /**
   * how many ortholog rows to align, `defaultMaxSpecies` when omitted. The
   * aligner is what this bounds: EBI runs at roughly half a second per row for
   * a ~1400aa protein, so a gene with 865 orthologs is a 7 minute job at no
   * cap.
   */
  maxSpecies?: number
  /** candidate gene identifiers off the feature, tried in order */
  geneCandidates: string[]
  msaAlgorithm: MsaAlgorithm
  /** plain JSON, not a Feature: see TranscriptRef */
  selectedTranscript?: TranscriptRef
  /**
   * The query row, named `<species>_query`. The launch dialog always supplies
   * it, translated from the
   * transcript the user picked, which is what `connectedFeature` maps genome
   * coordinates through. Omitted — a session spec naming a gene and nothing
   * else — the query row becomes NCBI's representative protein for the resolved
   * gene, the same choice every other row makes.
   */
  proteinSequence?: string
}

/**
 * #stateModel MsaViewPlugin
 * extends
 * - MSAModel from https://github.com/GMOD/react-msaview
 */
export default function stateModelFactory() {
  return types
    .compose(
      BaseViewModel,
      MSAModelF(),
      types.model('MsaView', {
        /**
         * #property
         */
        connectedViewId: types.maybe(types.string),
        /**
         * #property
         */
        connectedFeature: types.frozen(),
        /**
         * #property
         * the short form of `connectedFeature`: a transcript id (NM_000546.6)
         * looked up in the connected genome view's tracks at launch, so a
         * session spec can name the transcript instead of carrying its whole
         * exon model. Resolved once into `connectedFeature` and left in place.
         */
        connectedTranscript: types.maybe(types.string),
        /**
         * #property
         */
        blastParams: types.frozen<BlastParams | undefined>(),
        /**
         * #property
         */
        orthologParams: types.frozen<OrthologParams | undefined>(),
        /**
         * #property
         */
        querySeqName: types.stripDefault(types.string, 'QUERY'),

        /**
         * #property
         * transcript residues before the query row's first residue, so a
         * transcript position is a row position plus this. A pasted alignment
         * often carries only the aligned region of the query -- BLAST reports
         * what it aligned -- and mapping that row's first residue to the
         * transcript's first residue put every click off by the trimmed
         * amount. Negative when the row runs past the transcript's start.
         */
        querySeqOffset: types.stripDefault(types.number, 0),

        /**
         * #property
         */
        uniprotId: types.maybe(types.string),

        /**
         * #property
         */
        zoomToBaseLevel: types.stripDefault(types.boolean, false),

        /**
         * #property
         */
        init: types.frozen<MsaViewInitState | undefined>(),

        /**
         * #property
         */
        dataStoreId: types.maybe(types.string),

        /**
         * #property
         * whether the request above has already produced this view's alignment.
         *
         * The params used to be cleared to mark that, which threw away the only
         * statement of what the view is: browser storage expires an alignment
         * after 7 days, and the view could then only tell the user to start
         * over from the gene. A flag says the same thing and duplicates
         * nothing, where a kept copy of the request put a second protein
         * sequence and a second exon model in every saved session.
         *
         * A snapshot property rather than a volatile, because the case it
         * exists for is by construction a later session: expiry is discovered
         * by `loadStoredData` on restore, and a volatile would be false there
         * and refire the whole search unasked.
         */
        launchCompleted: false,

        /**
         * #property
         */
        mafRegion: types.frozen<MafRegion | undefined>(),

        /**
         * #property
         * react-msaview draws the toolbar's menus and Settings as icons, since
         * a JBrowse view shares its row with other panels. A session spec sets
         * it false for the labeled toolbar.
         */
        embeddedMode: true,

        /**
         * #property
         * a launch asking for the domains on the genome: once the connected
         * view and the query row's domains are both there, the view adds the
         * domain track and clears this
         */
        domainsOnGenome: types.stripDefault(types.boolean, false),
      }),
    )

    .volatile(
      (): {
        rid: string | undefined
        progress: string
        loadingStoredData: boolean
        isStoringData: boolean
        lastStoredData: MsaDataPayload | undefined
        ownsDataStoreRow: boolean
        launchController: AbortController | undefined
        domainsRequested: boolean
        loadingDomains: boolean
        connectionError: unknown
      } => ({
        /**
         * #volatile
         */
        rid: undefined,
        /**
         * #volatile
         */
        progress: '',
        /**
         * #volatile
         */
        loadingStoredData: false,
        /**
         * #volatile
         */
        isStoringData: false,
        /**
         * #volatile
         * what IndexedDB was last known to hold for this view, so an edit made
         * after the first write (react-msaview replacing data.tree with a
         * neighbor-joining tree, say) is recognized as needing a new one
         */
        lastStoredData: undefined,
        /**
         * #volatile
         * whether this view wrote the row `dataStoreId` names, this session;
         * a restored row may be shared with a copied view or a duplicated
         * session, so a write to one the view did not create takes a fresh id
         */
        ownsDataStoreRow: false,
        /**
         * #volatile
         * aborts the launch currently in flight -- from the Cancel button, and
         * from the disposer afterCreate registers, so a closed view stops
         * polling EBI instead of running to completion and writing to a node
         * that is gone
         */
        launchController: undefined,
        /**
         * #volatile
         * guards the one-shot auto-fetch of protein domains so it doesn't refire
         * when NCBI returns no domains (leaving the annotation list empty)
         */
        domainsRequested: false,
        /**
         * #volatile
         * the protein domain auto-load is in flight
         */
        loadingDomains: false,
        /**
         * #volatile
         * why `connectedTranscript` could not be resolved: the lookup missed,
         * or the genome view it needs is absent or has no feature tracks. It
         * is also the view's `error` when a launch was waiting on the
         * transcript, and a notice otherwise
         */
        connectionError: undefined,
      }),
    )

    .views(self => ({
      /**
       * #getter
       * the linked transcript's genome mapping, or why it has none
       */
      get transcriptMapping() {
        return self.connectedFeature
          ? transcriptMapping(self.connectedFeature)
          : undefined
      },

      /**
       * #getter
       * whatever view `connectedViewId` names, genome view or not
       */
      get viewNamedByConnectedViewId() {
        const { views } = getSession(self)
        return views.find(f => f.id === self.connectedViewId)
      },
    }))

    .views(self => ({
      /**
       * #getter
       * the view `connectedViewId` names, when it is a genome view
       */
      get connectedView(): LGV | undefined {
        const view = self.viewNamedByConnectedViewId
        return view && isLinearGenomeView(view) ? view : undefined
      },
    }))

    .views(self => ({
      /**
       * #getter
       */
      get transcriptToMsaMap() {
        const mapping = self.transcriptMapping
        return mapping && 'map' in mapping ? mapping.map : undefined
      },
    }))

    .views(self => ({
      /**
       * #getter
       * Genome regions under the current MSA hover column. Suppressed on the LGV
       * while it's being hovered (GenomeMouseoverHighlight shows the crisp 1bp
       * marker there instead of this wider codon band).
       */
      get connectedHoverHighlights(): IRegion[] {
        const { mouseCol } = self
        return mouseCol === undefined
          ? []
          : msaCoordToGenomeRegions({ model: self, coord: mouseCol })
      },
      /**
       * #getter
       * Genome regions under the persistent MSA click selection. Shown
       * regardless of LGV hover, so hovering the genome doesn't hide it.
       */
      get connectedClickHighlights(): IRegion[] {
        const { mouseClickCol } = self
        return mouseClickCol === undefined
          ? []
          : msaCoordToGenomeRegions({ model: self, coord: mouseClickCol })
      },
      /**
       * #getter
       * cross-plugin contract: jbrowse-plugin-mafviewer reads this off the view
       * to draw the same highlights in its own display
       */
      get connectedHighlights(): IRegion[] {
        return [
          ...this.connectedHoverHighlights,
          ...this.connectedClickHighlights,
        ]
      },
      /**
       * #getter
       * cross-plugin contract: the query row's domains on the genome, with
       * the color object every surface paints them through.
       * jbrowse-plugin-protein3d reads it to draw them on the structure
       */
      get connectedDomains(): ConnectedDomains {
        return connectedDomains(self)
      },
    }))

    .views(self => ({
      /**
       * #getter
       * overrides base
       *
       * react-msaview drops any snapshot document over 50kb and warns that a
       * link to the view opens without it. True for an alignment this browser
       * is holding in IndexedDB; wrong for an indexed view, whose kept `init`
       * names a bgzip block over HTTP that processInit refetches wherever the
       * session is opened -- so that one showed "Not in the link" about an
       * alignment the link does carry.
       */
      get hostRestoresData() {
        const { msaIndexedLocation, msaName } = self.init ?? {}
        // `hostCarriesData` first: it is the base answer, the volatile a simple
        // host flips, and overriding the getter without it threw that switch
        // away for every view this one does not speak for
        return self.hostCarriesData || !!(msaIndexedLocation && msaName)
      },
      /**
       * #getter
       * the documents a reload would lose: too big for react-msaview to keep
       * in the snapshot, and with no filehandle or kept init to refetch them
       * from. IndexedDB holds exactly these.
       */
      get unsavedDocuments(): MsaDataPayload {
        const { data, init } = self
        const inSnapshot = getSnapshot(data)
        const unsaved = (key: keyof MsaDataPayload, source: unknown) => {
          const text = data[key]
          return text && !source && !inSnapshot[key] ? text : undefined
        }
        return {
          msa: unsaved('msa', self.msaFilehandle ?? init?.msaIndexedLocation),
          tree: unsaved('tree', self.treeFilehandle),
          treeMetadata: unsaved('treeMetadata', self.treeMetadataFilehandle),
          gff: unsaved('gff', self.gffFilehandle),
        }
      },
      /**
       * #getter
       * what is wrong with the link to the genome, derived from the view's
       * state so each clears when its cause does. A connection failure that
       * is already the view's `error` is not repeated here.
       */
      get linkNotices() {
        const {
          connectionError,
          error,
          transcriptMapping,
          connectedFeature,
          mafRegion,
          querySeqName,
          dataInitialized,
        } = self
        return [
          ...(connectionError !== undefined && connectionError !== error
            ? [errorMessage(connectionError)]
            : []),
          ...(transcriptMapping && 'reason' in transcriptMapping
            ? [
                `The linked transcript is not mapped to the genome: ${transcriptMapping.reason}`,
              ]
            : []),
          ...((connectedFeature || mafRegion) &&
          dataInitialized &&
          !hasQueryRow(self)
            ? [
                `No row is named "${querySeqName}", the query row, so the alignment is not linked to the genome`,
              ]
            : []),
        ]
      },
      /**
       * #getter
       * true while a launch, stored data, a file, the transcript lookup or the
       * protein domains are still loading and no error has ended it. Every
       * term settles on failure. jb.waitReady, the app's ready marker and
       * screenshot tools read it for a view.
       */
      get showLoading() {
        const {
          connectedView,
          connectedTranscript,
          connectedFeature,
          connectionError,
        } = self
        return (
          !self.error &&
          (isLaunching(self) ||
            (self.loadingStoredData && !self.dataInitialized) ||
            self.isLoading ||
            self.loadingDomains ||
            (!!connectedTranscript &&
              !connectedFeature &&
              connectionError === undefined) ||
            (self.domainsOnGenome &&
              self.connectedDomains.features.length > 0 &&
              !!connectedView?.showLoading))
        )
      },
    }))

    .views(self => ({
      /**
       * #getter
       * overrides base
       *
       * react-msaview's load and data warnings, plus the plugin's link
       * notices, which the header's warning chip lists and dismisses alike
       */
      get warnings() {
        return [
          ...self.loadWarnings,
          ...[...self.dataWarnings, ...self.linkNotices].filter(
            w => !self.dismissedWarnings.includes(w),
          ),
        ]
      },
    }))

    .views(self => ({
      /**
       * #getter
       * what failed and left the view working: the messages the header's
       * warning chip lists. A notice does not end `showLoading`.
       */
      get notices() {
        return self.warnings
      },
    }))

    .views(self => ({
      /**
       * #getter
       * what the view resolved to, as plain JSON. See docs/reading-the-view.md
       */
      get report() {
        return viewReport(self)
      },
    }))

    .actions(self => ({
      /**
       * #action
       */
      setZoomToBaseLevel(arg: boolean) {
        self.zoomToBaseLevel = arg
      },
      /**
       * #action
       */
      setProgress(arg: string) {
        self.progress = arg
      },
      /**
       * #action
       */
      setRid(arg: string) {
        self.rid = arg
      },
      /**
       * #action
       */
      setBlastParams(args?: BlastParams) {
        self.blastParams = args
      },
      /**
       * #action
       */
      setConnectedFeature(arg?: Record<string, unknown>) {
        self.connectedFeature = arg
      },
      /**
       * #action
       */
      setOrthologParams(args?: OrthologParams) {
        self.orthologParams = args
      },
      /**
       * #action
       */
      setInit(arg?: MsaViewInitState) {
        self.init = arg
      },
      /**
       * #action
       */
      setQuerySeqName(arg: string) {
        self.querySeqName = arg
      },
      /**
       * #action
       */
      setUniprotId(arg?: string) {
        self.uniprotId = arg
      },
      /**
       * #action
       */
      setDataStoreId(arg?: string) {
        self.dataStoreId = arg
      },
      /**
       * #action
       */
      setLaunchCompleted(arg: boolean) {
        self.launchCompleted = arg
      },
      /**
       * #action
       */
      setLoadingStoredData(arg: boolean) {
        self.loadingStoredData = arg
      },
      /**
       * #action
       */
      setIsStoringData(arg: boolean) {
        self.isStoringData = arg
      },
      /**
       * #action
       */
      setLastStoredData(arg?: MsaDataPayload) {
        self.lastStoredData = arg
      },
      /**
       * #action
       */
      setOwnsDataStoreRow(arg: boolean) {
        self.ownsDataStoreRow = arg
      },
      /**
       * #action
       */
      setLaunchController(arg?: AbortController) {
        self.launchController = arg
      },
      /**
       * #action
       * Abandon the launch, in flight or failed. The EBI job keeps running on
       * their side — nothing here can recall it, and its JobLink stays valid —
       * so this only stops the polling and the writes it would make. Dropping
       * the request (the params, or the init) is what keeps it from refiring on
       * the next reload; the view falls back to the import form, which is where
       * react-msaview's own cancel leaves it too.
       */
      cancelLaunch() {
        self.launchController?.abort()
        self.launchController = undefined
        self.blastParams = undefined
        self.orthologParams = undefined
        self.init = undefined
        self.launchCompleted = false
        self.progress = ''
        self.rid = undefined
        self.error = undefined
      },
      /**
       * #action
       * Run the request again. The request IS the params, so re-stating them is
       * the whole retry: each is a frozen property, and a fresh object is a
       * change the launch autoruns wake on.
       *
       * A launch that already succeeded keeps its params and is marked
       * `launchCompleted`, so clearing that mark is the whole retry for a view
       * whose stored alignment expired.
       */
      retryLaunch() {
        self.launchController?.abort()
        self.launchController = undefined
        self.progress = ''
        self.rid = undefined
        self.error = undefined
        self.launchCompleted = false
        if (self.blastParams) {
          self.blastParams = { ...self.blastParams }
        }
        if (self.orthologParams) {
          self.orthologParams = { ...self.orthologParams }
        }
        if (self.init) {
          self.init = { ...self.init }
        }
      },
      /**
       * #action
       */
      setDomainsRequested(arg: boolean) {
        self.domainsRequested = arg
      },
      /**
       * #action
       */
      setLoadingDomains(arg: boolean) {
        self.loadingDomains = arg
      },
      /**
       * #action
       * `connectedTranscript` could not be resolved. A launch waiting on it
       * cannot run, so for one that is the view's error; an alignment from
       * anywhere else is still worth showing, so then it is a notice.
       */
      failConnection(e: unknown) {
        self.connectionError = e
        if (launchAwaitsTranscript(self)) {
          self.setError(e)
        }
      },
      /**
       * #action
       */
      clearConnectionFailure() {
        if (
          self.connectionError !== undefined &&
          self.error === self.connectionError
        ) {
          self.setError(undefined)
        }
        self.connectionError = undefined
      },
      /**
       * #action
       */
      setDomainsOnGenome(arg: boolean) {
        self.domainsOnGenome = arg
      },
      /**
       * #action
       * Add the query row's domains to the connected genome view as a session
       * track, replacing the one an earlier call added.
       */
      showDomainsOnGenome() {
        const session = getSession(self)
        const { connectedView, connectedDomains, connectedFeature } = self
        const assemblyName = connectedView?.assemblyNames[0]
        if (
          !connectedView ||
          !assemblyName ||
          connectedDomains.features.length === 0 ||
          !isSessionWithAddSessionTrack(session)
        ) {
          return
        }
        const feature = connectedFeature as Record<string, unknown> | undefined
        const label = [feature?.gene_name, feature?.gene, feature?.name].find(
          (v): v is string => typeof v === 'string' && v !== '',
        )
        const conf = domainTrackConf({
          viewId: self.id,
          assemblyName,
          name: `${label ?? self.querySeqName} domains (from the alignment)`,
          strand: self.mafRegion ? undefined : self.transcriptToMsaMap?.strand,
          domains: connectedDomains,
        })
        const existing = isSessionWithSessionTracks(session)
          ? session.sessionTracks.find(t => t.trackId === conf.trackId)
          : undefined
        if (existing && isSessionWithDeleteTrackConf(session)) {
          session.deleteTrackConf(existing)
        }
        if (session.addSessionTrackConf(conf)) {
          void connectedView.launchTrack(conf.trackId)
        }
      },
      /**
       * #action
       */
      handleMsaClick(coord: number) {
        const { connectedView, zoomToBaseLevel } = self
        const { assemblyManager } = getSession(self)
        const r2 = msaCoordToGenomeCoord({ model: self, coord })

        if (r2 && connectedView) {
          if (zoomToBaseLevel) {
            connectedView.navTo(r2)
          } else {
            connectedView.centerAt(
              r2.start,
              displayedRefName({
                displayedRegions: connectedView.displayedRegions,
                assembly: assemblyManager.get(
                  connectedView.assemblyNames[0] ?? '',
                ),
                refName: r2.refName,
              }),
            )
          }
        }
      },
    }))
    .actions(self => {
      const superSetMouseClickPos = self.setMouseClickPos.bind(self)

      return {
        /**
         * #action
         */
        setMouseClickPos(col?: number, row?: number) {
          superSetMouseClickPos(col, row)
          if (col !== undefined) {
            self.handleMsaClick(col)
          }
        },
      }
    })

    .actions(self => {
      const superReset = self.reset.bind(self)
      return {
        /**
         * #action
         * overrides base
         *
         * react-msaview's reset applies a snapshot filtered to its own
         * `preservedOnReset` list, and a downstream property is never on it:
         * returning to the import form dropped the view's name, un-minimized
         * it, and forgot the zoom-on-click preference. The volatiles fail the
         * other way -- applySnapshot cannot reach them, so the last file's
         * state carried into the next one and the domain auto-load, which fires
         * once per view, never fired again.
         */
        reset() {
          const { displayName, minimized, zoomToBaseLevel } = self
          superReset()
          if (displayName !== undefined) {
            self.setDisplayName(displayName)
          }
          self.setMinimized(minimized)
          self.setZoomToBaseLevel(zoomToBaseLevel)
          self.setDomainsRequested(false)
          self.setLastStoredData(undefined)
          self.setOwnsDataStoreRow(false)
          self.clearConnectionFailure()
        },
      }
    })

    .actions(self => {
      const superClearWarnings = self.clearWarnings.bind(self)
      return {
        /**
         * #action
         * overrides base, so dismissing the warning chip hides the link
         * notices too until their cause changes
         */
        clearWarnings() {
          superClearWarnings()
          self.dismissedWarnings = [
            ...self.dismissedWarnings,
            ...self.linkNotices,
          ]
        },
      }
    })

    .views(self => {
      const superMenuItems = self.menuItems.bind(self)
      return {
        /**
         * #method
         * overrides base
         */
        menuItems(): MenuItem[] {
          return [
            ...superMenuItems(),
            {
              label: 'Zoom to base level on click?',
              type: 'checkbox',
              checked: self.zoomToBaseLevel,
              onClick: () => {
                self.setZoomToBaseLevel(!self.zoomToBaseLevel)
              },
            },
            ...(self.connectedView && self.connectedDomains.features.length > 0
              ? [
                  {
                    label: 'Show domains on the genome',
                    onClick: () => {
                      self.showDomainsOnGenome()
                    },
                  },
                ]
              : []),
          ]
        },
      }
    })

    .actions(self => ({
      afterCreate() {
        runCleanup()
        // ties the launch to the view: closing one mid-BLAST used to leave the
        // poller running for the job's lifetime and then call actions on a
        // destroyed node, which surfaced as an unhandled rejection
        addDisposer(self, () => {
          self.launchController?.abort()
        })
        loadStoredData(self)
        for (const fn of [
          storeDataToIndexedDB,
          resolveConnectedTranscriptIfNeeded,
          launchBlastIfNeeded,
          launchOrthologsIfNeeded,
          processInit,
          autoLoadProteinDomains,
          showDomainsOnGenomeIfAsked,
        ]) {
          addDisposer(
            self,
            autorun(() => {
              fn(self)
            }),
          )
        }
        // these two keep per-reaction state across runs (a "did I set it?" flag),
        // so they're factories returning the autorun body rather than plain fns
        addDisposer(self, autorun(syncGenomeHoverToMsaColumn(self)))
        addDisposer(self, autorun(observeProteinHighlights(self)))
        addDisposer(self, autorun(syncSessionHighlights(self)))
      },
    }))
}

export type JBrowsePluginMsaViewStateModel = ReturnType<
  typeof stateModelFactory
>
export type JBrowsePluginMsaViewModel = Instance<JBrowsePluginMsaViewStateModel>

export { type MafRegion, type MsaViewInitState } from './types'
